// Pega cada resposta do Gemini e transforma o texto em campos separados
return $input.all().map(item => {
  const texto = item.json.content.parts[0].text;

  // Remove crases de bloco de código, caso o Gemini coloque
  const limpo = texto.replace(/```json|```/g, '').trim();

  const dados = JSON.parse(limpo);
  return { json: dados };
});
